'use client';
import React,{useEffect,useRef,useState} from 'react';
import type {RecordRow as R} from '@/lib/erp-primitives';
type Props={records:R[];company:string;sample:boolean;busy:boolean;act:(x:any)=>Promise<void>;onResult?:(r:any)=>void;initial?:{status?:any;result?:any;selectedId?:string}};
export default function OSAssistant({records,company,sample,busy,act,onResult,initial={}}:Props){
const [status,setStatus]=useState<any>(initial.status||null),[error,setError]=useState(''),[provider,setProvider]=useState('openai'),[intent,setIntent]=useState('draft'),[selectedId,setSelectedId]=useState(initial.selectedId||''),[instructions,setInstructions]=useState(''),[running,setRunning]=useState(false),[result,setResult]=useState<any>(initial.result||null),[draft,setDraft]=useState(initial.result?.result?.draft||'');
const lastRequest=useRef<any>(null),active=useRef(false);
async function refreshStatus(signal?:AbortSignal){try{const res=await fetch('/api/os-ai?company='+encodeURIComponent(company==='Group'?'Hagadol':company),{cache:'no-store',signal});const data:any=await res.json();if(!res.ok)throw Error(data.error);if(!signal?.aborted)setStatus(data);}catch(e){if(!signal?.aborted)setError((e as Error).message);}}
useEffect(()=>{if(sample)return;const c=new AbortController();void refreshStatus(c.signal);return()=>c.abort();},[sample,company]);
const choices=records.filter(r=>(company==='Group'||r.company===company)&&r.type===(intent==='draft'?'bid':'proposal')),selected=choices.find(r=>r.id===selectedId),ready=provider==='both'?status?.openai?.ready&&status?.claude?.ready:status?.[provider]?.ready;
async function generate(retry=false){if(active.current||!selected||sample)return;active.current=true;setRunning(true);setError('');setResult(null);try{const body=retry&&lastRequest.current?lastRequest.current:{recordId:selected.id,expectedVersion:selected.version,provider,intent,instructions,requestId:crypto.randomUUID()};lastRequest.current=body;const res=await fetch('/api/os-ai',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify(body)});const data:any=await res.json();if(!res.ok)throw Error(data.error||'The AI request failed.');setResult(data);setDraft(data.result.draft);onResult?.(data);}catch(e){setError((e as Error).message);}finally{setRunning(false);active.current=false;await refreshStatus();}}
const alreadySaved=!!result&&records.some(r=>r.type==='proposal'&&r.aiGenerationRunId===result.id);const currentSource=result&&records.find(r=>r.id===result.result.sourceId),stale=!!(result&&(!currentSource||currentSource.version!==result.result.sourceVersion));
return <section className="osassistant" aria-busy={running}><header className="panelhead"><div><h2>OS assistant</h2><p>Choose OpenAI, Claude, or OpenAI drafting followed by Claude review.</p></div><span className="status">{sample?'Live setup required':status?'Provider setup checked':'Checking provider setup'}</span></header>
<p className="notice">{sample?'The sample workspace uses the template builder. Switch to Live workspace to use AI on saved bids.':'The selected bid brief, buyer details, evidence and commercial terms are sent to the chosen provider. A combined run also sends its generated draft to Claude. AI results require human review.'}</p>
<div className="aistatus"><span>OpenAI: {status?.openai?.ready?'Configured':'Awaiting API account and model'}</span><span>Claude: {status?.claude?.ready?'Configured':'Awaiting API account and model'}</span><span>Daily company limit: {status?.dailyLimit||10} provider calls</span></div>
<div className="aiform"><label>Action<select value={intent} disabled={running} onChange={e=>{setIntent(e.target.value);if(provider==='both')setProvider('openai');setSelectedId('');setResult(null);lastRequest.current=null;}}><option value="draft">Draft from a bid</option><option value="review">Review a saved proposal</option></select></label><label>Provider<select value={provider} disabled={running} onChange={e=>{setProvider(e.target.value);lastRequest.current=null;setResult(null);}}><option value="openai">OpenAI</option><option value="claude">Claude</option>{intent==='draft'&&<option value="both">OpenAI draft + Claude review</option>}</select></label><label>Saved {intent==='draft'?'bid':'proposal'}<select value={selectedId} disabled={running} onChange={e=>{setSelectedId(e.target.value);setResult(null);lastRequest.current=null;}}><option value="">Choose a record</option>{choices.map(r=><option key={r.id} value={r.id}>{r.company} · {r.name}</option>)}</select></label><label className="fullwidth">Drafting or review focus<textarea maxLength={2000} rows={3} value={instructions} disabled={running} onChange={e=>{setInstructions(e.target.value);lastRequest.current=null;}} placeholder="For example, highlight missing buyer documents and delivery assumptions"/></label></div>
<div className="recordactions"><button className="primary" disabled={sample||busy||running||!selected||!ready} onClick={()=>generate()}>{running?'Working on the request…':intent==='draft'?'Generate working draft':'Review proposal'}</button><button className="secondary" disabled={sample||running} onClick={()=>refreshStatus()}>Check provider setup</button></div>
{error&&<div className="modalerror" role="alert">{error}{lastRequest.current&&<button className="textbutton" disabled={running||sample} onClick={()=>generate(true)}>Retrieve or retry the same request</button>}</div>}
{result&&<div className="airesult"><h3>{intent==='draft'?'Review the generated draft':'AI review findings'}</h3><p>{result.result.runs.map((r:any)=>r.provider+' · '+r.model).join(' | ')} · {result.result.status}</p>{stale&&<p role="alert" className="notice">The saved source changed. Generate a new result before saving.</p>}{intent==='draft'&&<label>Editable working draft<textarea rows={16} maxLength={50000} value={draft} onChange={e=>setDraft(e.target.value)}/></label>}{result.result.review&&<div className="aifindings"><h4>Independent review notes</h4><p>{result.result.review}</p></div>}<button className="secondary" disabled={busy||stale||intent==='draft'&&alreadySaved||!draft.trim()} onClick={()=>{if(!currentSource)return;if(intent==='draft')void act({action:'create',type:'proposal',company:currentSource.company,name:currentSource.name+' proposal',customer:currentSource.customer,sourceBid:currentSource.id,sourceBidVersion:result.result.sourceVersion,document:draft,aiRunId:result.id,aiReview:result.result.review,due:currentSource.due});else void act({action:'edit',id:currentSource.id,expectedVersion:result.result.sourceVersion,aiRunId:result.id,fields:{aiReview:result.result.review}});}}>{intent==='draft'&&alreadySaved?'Working draft saved':'Save '+(intent==='draft'?'working draft':'review notes')}</button></div>}
{status?.history?.length>0&&<details className="airunhistory"><summary>Recent AI runs for {company==='Group'?'Hagadol':company}</summary><table><thead><tr><th>When</th><th>Provider</th><th>Action</th><th>Result</th></tr></thead><tbody>{status.history.map((r:any)=><tr key={r.id}><td>{new Date(r.created).toLocaleString('en-GB',{timeZone:'Africa/Kampala'})}</td><td>{r.provider}</td><td>{r.intent}</td><td>{r.status}{r.failure?' · '+r.failure:''}</td></tr>)}</tbody></table></details>}
<p className="footnote">Saved AI results stay in the private workspace. API accounts and provider billing must be configured before activation. No ledger entries, emails or submissions are made by the assistant.</p></section>;
}
